ALTER TABLE transactions ADD CONSTRAINT transactions_settled_range CHECK (((amount_settled >= (0)::numeric) AND (amount_settled <= amount)));
ALTER TABLE transactions ADD CONSTRAINT transactions_status_check CHECK ((status = ANY (ARRAY['ke_hoach'::text, 'den_han'::text, 'hoan_thanh_mot_phan'::text, 'hoan_thanh'::text, 'qua_han'::text])));
ALTER TABLE user_aliases ADD CONSTRAINT user_aliases_len CHECK (((char_length(btrim(alias)) >= 1) AND (char_length(btrim(alias)) <= 40)));
ALTER TABLE user_aliases ADD CONSTRAINT user_aliases_not_self CHECK ((owner_user_id <> target_user_id));
ALTER TABLE user_blocks ADD CONSTRAINT user_blocks_not_self CHECK ((blocker_id <> blocked_id));
ALTER TABLE user_connections ADD CONSTRAINT user_connections_ordered CHECK ((user_low < user_high));
ALTER TABLE user_connections ADD CONSTRAINT user_connections_source_check CHECK ((source = ANY (ARRAY['pin'::text, 'group'::text, 'contact_invite'::text, 'legacy'::text])));
ALTER TABLE user_connections ADD CONSTRAINT user_connections_status_check CHECK ((status = ANY (ARRAY['active'::text, 'removed'::text])));
ALTER TABLE user_pins ADD CONSTRAINT user_pins_format CHECK ((pin ~ '^A-[ABCDEFGHJKLMNPQRSTUVWXYZ][ABCDEFGHJKLMNPQRSTUVWXYZ2-9]{6}[ABCDEFGHJKLMNPQRSTUVWXYZ]$'::text));
ALTER TABLE user_pins ADD CONSTRAINT user_pins_letters CHECK ((char_length(regexp_replace(substr(pin, 3), '[^A-Z]'::text, ''::text, 'g'::text)) >= 4));
ALTER TABLE user_pins ADD CONSTRAINT user_pins_source CHECK ((source = ANY (ARRAY['chosen'::text, 'generated'::text])));
ALTER TABLE user_reports ADD CONSTRAINT user_reports_content_len CHECK (((reported_content IS NULL) OR (char_length(reported_content) <= 4000)));
ALTER TABLE user_reports ADD CONSTRAINT user_reports_not_self CHECK ((reporter_id <> reported_user_id));
ALTER TABLE user_reports ADD CONSTRAINT user_reports_note_len CHECK (((note IS NULL) OR (char_length(note) <= 500)));
ALTER TABLE user_reports ADD CONSTRAINT user_reports_reason_check CHECK ((reason = ANY (ARRAY['harassment'::text, 'scam'::text, 'inappropriate'::text, 'impersonation'::text, 'other'::text])));
ALTER TABLE vault_files ADD CONSTRAINT vault_files_bytes_check CHECK (((bytes >= 1) AND (bytes <= (20971520 + 64))));
ALTER TABLE vault_files ADD CONSTRAINT vault_files_mime_class_check CHECK ((mime_class = ANY (ARRAY['image'::text, 'pdf'::text])));
ALTER TABLE vault_files ADD CONSTRAINT vault_files_page_no_check CHECK (((page_no >= 1) AND (page_no <= 20)));
ALTER TABLE vault_items ADD CONSTRAINT vault_items_reminder_title_check CHECK (((reminder_title IS NULL) OR (char_length(reminder_title) <= 120)));
ALTER TABLE vault_items ADD CONSTRAINT vault_items_section_check CHECK ((section = ANY (ARRAY['certificates'::text, 'documents'::text, 'assets'::text])));
